import {
  callPlugin as nativeCallPlugin,
  getDeviceInfo as nativeGetDeviceInfo,
  openCamera as nativeOpenCamera,
  openCameraIDCard as nativeOpenCameraIDCard,
  executeBiometric as nativeExecuteBiometric,
  openLocationCamera as nativeOpenLocationCamera,
  downloadOTA as nativeDownloadOTA,
  playHaptic as nativePlayHaptic,
  openDeveloperConsole as nativeOpenDeveloperConsole,
  openDeveloperSettings as nativeOpenDeveloperSettings,
  CallPluginOptions,
} from 'react-native-bizmob-plugin';
import { appLogger } from '../logger/AppLogger';
import {
  defaultNetworkService,
  NetworkRequestOptions,
  NetworkResponse,
} from '../network/NetworkService';

export interface PluginResponseHeader {
  result: boolean;
  error_code: string;
  error_text: string;
}

export interface PluginResponse<T = any> {
  header: PluginResponseHeader;
  body: T;
}

export interface DeviceInfoData {
  deviceId: string;
  osType: string;
  osVersion: string;
  model?: string;
  manufacturer?: string;
  language?: string;
}

export interface CameraResult {
  imagePath?: string;
  imageBase64?: string;
  fileSize?: number;
}

export interface IDCardScanResult {
  idNumber?: string;
  fullName?: string;
  dateOfBirth?: string;
  address?: string;
  cardImageBase64?: string;
}

export interface BiometricAuthResult {
  authenticated: boolean;
  token?: string;
}

export interface LocationCameraResult {
  latitude: number;
  longitude: number;
  address?: string;
  imagePath?: string;
}

export interface IPluginBridgeService {
  getDeviceInfo(): Promise<DeviceInfoData | null>;
  openCamera(options?: Record<string, any>): Promise<CameraResult | null>;
  scanIDCard(options?: Record<string, any>): Promise<IDCardScanResult | null>;
  authenticateBiometric(promptMessage?: string): Promise<BiometricAuthResult>;
  captureLocationPhoto(options?: Record<string, any>): Promise<LocationCameraResult | null>;
  playHapticFeedback(): Promise<void>;
  openDeveloperConsole(options?: Record<string, any>): Promise<boolean>;
  openDeveloperSettings(options?: Record<string, any>): Promise<boolean>;
  callCustomPlugin<TResult = any, TParams = Record<string, any>>(
    pluginIdOrOptions: string | CallPluginOptions<TParams, TResult>,
    params?: TParams
  ): Promise<TResult>;
  requestNetwork<TData = any, TPayload = Record<string, any>>(
    options: NetworkRequestOptions<TPayload>
  ): Promise<NetworkResponse<TData>>;
}

export class PluginBridgeService implements IPluginBridgeService {
  async getDeviceInfo(): Promise<DeviceInfoData | null> {
    appLogger.i('[PluginBridgeService] Request: getDeviceInfo()');
    try {
      const response: any = await nativeGetDeviceInfo();
      appLogger.i('[PluginBridgeService] Response: getDeviceInfo()', response);
      const body = response?.body || response;
      if (body) {
        return {
          deviceId: body.device_id || body.device_uuid || '',
          osType: body.os_type || '',
          osVersion: body.os_version || '',
          model: body.model,
          manufacturer: body.manufacturer,
          language: body.language,
        };
      }
      return null;
    } catch (error) {
      appLogger.e('[PluginBridgeService] Failed: getDeviceInfo()', error);
      console.warn('[PluginBridgeService] Failed to retrieve device info:', error);
      return null;
    }
  }

  async openCamera(options?: Record<string, any>): Promise<CameraResult | null> {
    appLogger.i('[PluginBridgeService] Request: openCamera()', options);
    try {
      const response: any = await nativeOpenCamera(options);
      appLogger.i('[PluginBridgeService] Response: openCamera()', response);
      if (response?.header?.result) {
        return {
          imagePath: response.body?.image_path,
          imageBase64: response.body?.image_base64,
          fileSize: response.body?.file_size,
        };
      }
      return null;
    } catch (error) {
      appLogger.e('[PluginBridgeService] Failed: openCamera()', error);
      console.warn('[PluginBridgeService] Camera capture failed:', error);
      return null;
    }
  }

  async scanIDCard(options?: Record<string, any>): Promise<IDCardScanResult | null> {
    appLogger.i('[PluginBridgeService] Request: scanIDCard()', options);
    try {
      const response: any = await nativeOpenCameraIDCard(options);
      appLogger.i('[PluginBridgeService] Response: scanIDCard()', response);
      if (response?.header?.result) {
        return {
          idNumber: response.body?.id_number,
          fullName: response.body?.full_name,
          dateOfBirth: response.body?.dob,
          address: response.body?.address,
          cardImageBase64: response.body?.card_image,
        };
      }
      return null;
    } catch (error) {
      appLogger.e('[PluginBridgeService] Failed: scanIDCard()', error);
      console.warn('[PluginBridgeService] ID Card scan failed:', error);
      return null;
    }
  }

  async authenticateBiometric(promptMessage = 'Verify your identity'): Promise<BiometricAuthResult> {
    appLogger.i('[PluginBridgeService] Request: authenticateBiometric()', { promptMessage });
    try {
      const response: any = await nativeExecuteBiometric({ prompt: promptMessage });
      appLogger.i('[PluginBridgeService] Response: authenticateBiometric()', response);
      const isSuccess = response?.header?.result === true;
      return {
        authenticated: isSuccess,
        token: response?.body?.token,
      };
    } catch (error) {
      appLogger.e('[PluginBridgeService] Failed: authenticateBiometric()', error);
      console.warn('[PluginBridgeService] Biometric authentication failed:', error);
      return { authenticated: false };
    }
  }

  async captureLocationPhoto(options?: Record<string, any>): Promise<LocationCameraResult | null> {
    appLogger.i('[PluginBridgeService] Request: captureLocationPhoto()', options);
    try {
      const response: any = await nativeOpenLocationCamera(options);
      appLogger.i('[PluginBridgeService] Response: captureLocationPhoto()', response);
      if (response?.header?.result) {
        return {
          latitude: response.body?.latitude || 0,
          longitude: response.body?.longitude || 0,
          address: response.body?.address,
          imagePath: response.body?.image_path,
        };
      }
      return null;
    } catch (error) {
      appLogger.e('[PluginBridgeService] Failed: captureLocationPhoto()', error);
      console.warn('[PluginBridgeService] Location camera capture failed:', error);
      return null;
    }
  }

  async playHapticFeedback(): Promise<void> {
    appLogger.i('[PluginBridgeService] Request: playHapticFeedback()');
    try {
      await nativePlayHaptic();
      appLogger.i('[PluginBridgeService] Response: playHapticFeedback() success');
    } catch (error) {
      appLogger.e('[PluginBridgeService] Failed: playHapticFeedback()', error);
      console.warn('[PluginBridgeService] Haptic playback failed:', error);
    }
  }

  async openDeveloperConsole(options?: Record<string, any>): Promise<boolean> {
    appLogger.i('[PluginBridgeService] Request: openDeveloperConsole()', options);
    try {
      const response = await nativeOpenDeveloperConsole(options);
      appLogger.i('[PluginBridgeService] Response: openDeveloperConsole()', response);
      return response?.header?.result ?? true;
    } catch (error) {
      appLogger.e('[PluginBridgeService] Failed: openDeveloperConsole()', error);
      console.warn('[PluginBridgeService] openDeveloperConsole failed:', error);
      return false;
    }
  }

  async openDeveloperSettings(options?: Record<string, any>): Promise<boolean> {
    appLogger.i('[PluginBridgeService] Request: openDeveloperSettings()', options);
    try {
      const response = await nativeOpenDeveloperSettings(options);
      appLogger.i('[PluginBridgeService] Response: openDeveloperSettings()', response);
      return response?.header?.result ?? true;
    } catch (error) {
      appLogger.e('[PluginBridgeService] Failed: openDeveloperSettings()', error);
      console.warn('[PluginBridgeService] openDeveloperSettings failed:', error);
      return false;
    }
  }

  async callCustomPlugin<TResult = any, TParams = Record<string, any>>(
    pluginIdOrOptions: string | CallPluginOptions<TParams, TResult>,
    params?: TParams
  ): Promise<TResult> {
    const pluginId = typeof pluginIdOrOptions === 'string' ? pluginIdOrOptions : (pluginIdOrOptions.pluginId || pluginIdOrOptions.serviceId || 'UNKNOWN');
    appLogger.i(`[PluginBridgeService] Request: callCustomPlugin(${pluginId})`, params || pluginIdOrOptions);
    try {
      const result = await nativeCallPlugin<TResult, TParams>(pluginIdOrOptions, params);
      appLogger.i(`[PluginBridgeService] Response: callCustomPlugin(${pluginId})`, result);
      return result;
    } catch (error) {
      appLogger.e(`[PluginBridgeService] Failed: callCustomPlugin(${pluginId})`, error);
      throw error;
    }
  }

  async requestNetwork<TData = any, TPayload = Record<string, any>>(
    options: NetworkRequestOptions<TPayload>
  ): Promise<NetworkResponse<TData>> {
    return defaultNetworkService.request<TData, TPayload>(options);
  }
}

export const defaultPluginBridge = new PluginBridgeService();

