import { AppsFlyer, AFInAppEventType } from 'react-native-appsflyer';

/**
 * Interface definition for AppsFlyer initialization configuration.
 */
export interface AppsFlyerConfig {
  devKey: string;
  appId?: string; // Mandatory for iOS, optional for Android
  isDebug?: boolean;
  timeToWaitForATTUserAuthorization?: number; // In seconds (iOS only)
  onInstallConversionDataListener?: boolean;
  onDeepLinkListener?: boolean;
}

/**
 * Standard attribution and conversion data callback model.
 */
export interface ConversionDataResult {
  status: 'success' | 'failure';
  type?: 'install' | 're-engagement' | 'organic';
  data?: Record<string, unknown>;
  error?: unknown;
}

/**
 * Standard unified deep link payload model.
 */
export interface DeepLinkResult {
  status: 'FOUND' | 'NOT_FOUND' | 'ERROR';
  deepLinkValue?: string;
  mediaSource?: string;
  campaign?: string;
  isDeferred?: boolean;
  rawPayload?: Record<string, unknown>;
  error?: string;
}

/**
 * Standard contract for AppsFlyer Service.
 */
export interface IAppsFlyerService {
  init(config: AppsFlyerConfig): Promise<boolean>;
  start(): Promise<boolean>;
  stop(shouldStop?: boolean): Promise<boolean>;
  logEvent(eventName: string, eventValues?: Record<string, unknown>): Promise<boolean>;
  setCustomerUserId(userId: string): Promise<boolean>;
  setUserEmails(emails: string[]): Promise<boolean>;
  setAdditionalData(customData: Record<string, unknown>): Promise<boolean>;
  setCurrency(currencyCode: string): Promise<boolean>;
  getAppsFlyerUID(): Promise<string | null>;
  anonymizeUser(shouldAnonymize: boolean): Promise<boolean>;
  onConversionData(callback: (result: ConversionDataResult) => void): () => void;
  onDeepLink(callback: (result: DeepLinkResult) => void): () => void;
  isInitialized(): boolean;
  resetForTesting(): void;
}

/**
 * Production-ready AppsFlyer Analytics & Attribution Manager.
 */
export class AppsFlyerService implements IAppsFlyerService {
  private _isInitialized = false;
  private _sdk = AppsFlyer;
  private _conversionListeners: Set<(result: ConversionDataResult) => void> = new Set();
  private _deepLinkListeners: Set<(result: DeepLinkResult) => void> = new Set();
  private _hasRegisteredSdkConversionListener = false;
  private _hasRegisteredSdkDeepLinkListener = false;

  constructor(sdkInstance?: typeof AppsFlyer) {
    if (sdkInstance) {
      this._sdk = sdkInstance;
    }
  }

  public isInitialized(): boolean {
    return this._isInitialized;
  }

  /**
   * Initialize the AppsFlyer SDK with developer key and optional settings.
   */
  public async init(config: AppsFlyerConfig): Promise<boolean> {
    if (!config?.devKey) {
      console.warn('[AppsFlyerService] Missing required devKey for AppsFlyer initialization.');
      return false;
    }

    try {
      if (config.isDebug !== undefined && typeof this._sdk.enableDebug === 'function') {
        await this._sdk.enableDebug({ enabled: config.isDebug });
      }

      if (config.onInstallConversionDataListener) {
        this.setupSdkConversionListener();
      }

      if (config.onDeepLinkListener) {
        this.setupSdkDeepLinkListener();
      }

      await this._sdk.init({
        devKey: config.devKey,
        appId: config.appId || null,
      });

      this._isInitialized = true;
      return true;
    } catch (error) {
      console.error('[AppsFlyerService] init failed:', error);
      this._isInitialized = false;
      return false;
    }
  }

  /**
   * Start SDK tracking. Should be invoked after init or on session ready.
   */
  public async start(): Promise<boolean> {
    try {
      if (typeof this._sdk.start === 'function') {
        await this._sdk.start({ awaitResponse: true });
        return true;
      }
      return false;
    } catch (error) {
      console.error('[AppsFlyerService] start failed:', error);
      return false;
    }
  }

  /**
   * Opt-out / stop tracking.
   */
  public async stop(shouldStop = true): Promise<boolean> {
    try {
      if (typeof this._sdk.stop === 'function') {
        await this._sdk.stop({ shouldStop });
        return true;
      }
      return false;
    } catch (error) {
      console.error('[AppsFlyerService] stop failed:', error);
      return false;
    }
  }

  /**
   * Log an in-app event with key-value payload.
   */
  public async logEvent(eventName: string, eventValues: Record<string, unknown> = {}): Promise<boolean> {
    if (!eventName) {
      console.warn('[AppsFlyerService] Event name must not be empty.');
      return false;
    }

    try {
      if (typeof this._sdk.logEvent === 'function') {
        await this._sdk.logEvent({
          eventName,
          eventValues,
          awaitResponse: true,
        });
        return true;
      }
      return false;
    } catch (error) {
      console.error(`[AppsFlyerService] Failed to log event "${eventName}":`, error);
      return false;
    }
  }

  /**
   * Set the Customer User ID (e.g. CIF, account ID, or user UUID).
   */
  public async setCustomerUserId(userId: string): Promise<boolean> {
    if (!userId) {
      console.warn('[AppsFlyerService] User ID must not be empty.');
      return false;
    }

    try {
      if (typeof this._sdk.setCustomerUserId === 'function') {
        await this._sdk.setCustomerUserId({ customerId: userId });
        return true;
      }
      return false;
    } catch (error) {
      console.error('[AppsFlyerService] Failed to setCustomerUserId:', error);
      return false;
    }
  }

  /**
   * Set user emails for web-to-app or cross-channel attribution.
   */
  public async setUserEmails(emails: string[]): Promise<boolean> {
    if (!emails || emails.length === 0) {
      return false;
    }

    try {
      if (typeof this._sdk.setUserEmail === 'function') {
        for (const email of emails) {
          if (email) {
            await this._sdk.setUserEmail({ email });
          }
        }
        return true;
      }
      return false;
    } catch (error) {
      console.error('[AppsFlyerService] Failed to setUserEmails:', error);
      return false;
    }
  }

  /**
   * Set custom global session metadata / additional params.
   */
  public async setAdditionalData(customData: Record<string, unknown>): Promise<boolean> {
    try {
      if (typeof this._sdk.setAdditionalData === 'function') {
        await this._sdk.setAdditionalData({ customData });
        return true;
      }
      return false;
    } catch (error) {
      console.error('[AppsFlyerService] Failed to setAdditionalData:', error);
      return false;
    }
  }

  /**
   * Set default currency code (e.g., 'USD', 'KHR').
   */
  public async setCurrency(currencyCode: string): Promise<boolean> {
    if (!currencyCode) {
      return false;
    }

    try {
      if (typeof this._sdk.setCurrencyCode === 'function') {
        await this._sdk.setCurrencyCode({ currencyCode });
        return true;
      }
      return false;
    } catch (error) {
      console.error('[AppsFlyerService] Failed to setCurrencyCode:', error);
      return false;
    }
  }

  /**
   * Retrieve the unique AppsFlyer device identifier.
   */
  public async getAppsFlyerUID(): Promise<string | null> {
    try {
      if (typeof this._sdk.getAppsFlyerUID === 'function') {
        return await this._sdk.getAppsFlyerUID();
      }
      return null;
    } catch (error) {
      console.error('[AppsFlyerService] Failed to getAppsFlyerUID:', error);
      return null;
    }
  }

  /**
   * Anonymize user tracking for GDPR / regulatory compliance.
   */
  public async anonymizeUser(shouldAnonymize: boolean): Promise<boolean> {
    try {
      if (typeof this._sdk.anonymizeUser === 'function') {
        await this._sdk.anonymizeUser({ shouldAnonymize });
        return true;
      }
      return false;
    } catch (error) {
      console.error('[AppsFlyerService] Failed to anonymizeUser:', error);
      return false;
    }
  }

  /**
   * Subscribe to install attribution / conversion data.
   * Returns an unsubscribe function.
   */
  public onConversionData(callback: (result: ConversionDataResult) => void): () => void {
    this._conversionListeners.add(callback);
    this.setupSdkConversionListener();

    return () => {
      this._conversionListeners.delete(callback);
    };
  }

  /**
   * Subscribe to deep link attribution events (Unified Deep Linking - UDL).
   * Returns an unsubscribe function.
   */
  public onDeepLink(callback: (result: DeepLinkResult) => void): () => void {
    this._deepLinkListeners.add(callback);
    this.setupSdkDeepLinkListener();

    return () => {
      this._deepLinkListeners.delete(callback);
    };
  }

  private setupSdkConversionListener(): void {
    if (this._hasRegisteredSdkConversionListener) return;
    if (typeof this._sdk.registerConversionListener !== 'function') return;

    this._hasRegisteredSdkConversionListener = true;
    this._sdk.registerConversionListener({
      onConversionDataSuccess: (data: Record<string, unknown>) => {
        const statusType = (data?.af_status as string) || '';
        const mappedType =
          statusType === 'Organic'
            ? 'organic'
            : statusType === 'Non-organic'
            ? 'install'
            : 're-engagement';

        const result: ConversionDataResult = {
          status: 'success',
          type: mappedType,
          data,
        };

        this._conversionListeners.forEach(listener => {
          try {
            listener(result);
          } catch (e) {
            console.error('[AppsFlyerService] Conversion listener threw an error:', e);
          }
        });
      },
      onConversionDataFail: (error: unknown) => {
        const result: ConversionDataResult = {
          status: 'failure',
          error,
        };

        this._conversionListeners.forEach(listener => {
          try {
            listener(result);
          } catch (e) {
            console.error('[AppsFlyerService] Conversion failure listener threw an error:', e);
          }
        });
      },
    }).catch(err => {
      console.warn('[AppsFlyerService] Failed to register conversion listener on SDK:', err);
    });
  }

  private setupSdkDeepLinkListener(): void {
    if (this._hasRegisteredSdkDeepLinkListener) return;
    if (typeof this._sdk.registerDeepLinkListener !== 'function') return;

    this._hasRegisteredSdkDeepLinkListener = true;
    this._sdk.registerDeepLinkListener({
      onDeepLinking: (data: any) => {
        const deepLinkObj = data?.deepLink || {};
        const result: DeepLinkResult = {
          status: data?.status || 'NOT_FOUND',
          deepLinkValue: deepLinkObj?.deep_link_value as string,
          mediaSource: deepLinkObj?.media_source as string,
          campaign: deepLinkObj?.campaign as string,
          isDeferred: Boolean(deepLinkObj?.is_deferred),
          rawPayload: deepLinkObj,
          error: data?.error,
        };

        this._deepLinkListeners.forEach(listener => {
          try {
            listener(result);
          } catch (e) {
            console.error('[AppsFlyerService] Deep link listener threw an error:', e);
          }
        });
      },
    }).catch(err => {
      console.warn('[AppsFlyerService] Failed to register deep link listener on SDK:', err);
    });
  }

  public resetForTesting(): void {
    this._isInitialized = false;
    this._conversionListeners.clear();
    this._deepLinkListeners.clear();
    this._hasRegisteredSdkConversionListener = false;
    this._hasRegisteredSdkDeepLinkListener = false;
  }
}

/**
 * Standard in-app event names re-exported for application-wide consistency.
 */
export const AppsFlyerEventTypes = AFInAppEventType;

/**
 * Default singleton instance.
 */
export const appsFlyerService = new AppsFlyerService();
export default appsFlyerService;

