import {
  trackActivity,
  logTrace,
  addActivityTrackingListener,
  logFirebaseAnalyticsEvent,
  type ActivityTrackingRequest,
  type ActivityTrackingResult,
  type BizmobEventSubscription,
} from 'react-native-bizmob-plugin';

/**
 * Standard user profile & traits for CMP targeting.
 */
export interface CmpUserProfile {
  userId: string;
  cif?: string;
  phoneNumber?: string;
  email?: string;
  branchCode?: string;
  customerSegment?: 'RETAIL' | 'SME' | 'CORPORATE' | 'VIP' | string;
  registeredDate?: string;
  language?: string;
  customAttributes?: Record<string, string | number | boolean>;
}

/**
 * Standard product engagement event request.
 */
export interface CmpProductEngagementParams {
  productId: string;
  productName: string;
  category: 'LOAN' | 'CARD' | 'DEPOSIT' | 'INSURANCE' | string;
  productAction: 'VIEW' | 'SELECT' | 'APPLY' | 'CALCULATE' | 'PURCHASE';
  amount?: number;
  currency?: string;
  tenureMonths?: number;
  extraData?: Record<string, unknown>;
}

/**
 * Standard multi-step funnel step request.
 */
export interface CmpFunnelStepParams {
  funnelName: string;
  stepNumber: number;
  stepName: string;
  applicationId?: string;
  productCode?: string;
  extraData?: Record<string, unknown>;
}

/**
 * Contract for Customer Marketing Platform (CMP) tracking service.
 */
export interface ICmpService {
  init(defaultChannelId?: string): Promise<boolean>;
  identifyUser(profile: CmpUserProfile): Promise<boolean>;
  trackEvent(eventName: string, properties?: Record<string, unknown>): Promise<boolean>;
  trackProductEngagement(params: CmpProductEngagementParams): Promise<boolean>;
  trackFunnelStep(params: CmpFunnelStepParams): Promise<boolean>;
  trackScreen(screenName: string, fromScreen?: string): Promise<boolean>;
  onActivityEvent(callback: (event: Record<string, unknown>) => void): () => void;
  setLogging(enabled: boolean): Promise<boolean>;
  getHistory(): Promise<Array<Record<string, unknown>>>;
  clearHistory(): Promise<boolean>;
}

/**
 * Enterprise CMP Service managing user lifecycle, loan funnels, and marketing engagement channels.
 */
export class CmpService implements ICmpService {
  private _isInitialized = false;
  private _currentUser: CmpUserProfile | null = null;
  private _defaultChannelId = 'LOS_MOBILE';

  public async init(defaultChannelId = 'LOS_MOBILE'): Promise<boolean> {
    this._defaultChannelId = defaultChannelId;
    this._isInitialized = true;
    return true;
  }

  public isInitialized(): boolean {
    return this._isInitialized;
  }

  public getCurrentUser(): CmpUserProfile | null {
    return this._currentUser;
  }

  /**
   * Set user profile & marketing traits. Guarantees MKT can target audience segments.
   */
  public async identifyUser(profile: CmpUserProfile): Promise<boolean> {
    if (!profile?.userId) {
      console.warn('[CmpService] identifyUser requires a valid userId.');
      return false;
    }

    this._currentUser = profile;

    try {
      // 1. Dispatch profile to native Firebase / Cloud Messaging bridge
      await logFirebaseAnalyticsEvent({
        action: 'user_profile_sync',
        user_id: profile.userId,
        uid: profile.cif || profile.userId,
        user_properties: {
          customer_segment: profile.customerSegment || 'RETAIL',
          branch_code: profile.branchCode || 'DEFAULT',
          language: profile.language || 'en',
          ...(profile.customAttributes || {}),
        },
        data: {
          phone_number: profile.phoneNumber || '',
          email: profile.email || '',
          registered_date: profile.registeredDate || '',
        },
      });

      // 2. Dispatch to Activity Tracking native telemetry store
      await trackActivity({
        action: 'track_event',
        event_type: 'USER_IDENTIFIED',
        id: profile.userId,
        text: profile.customerSegment || 'RETAIL',
        data: {
          cif: profile.cif,
          customer_segment: profile.customerSegment,
          branch_code: profile.branchCode,
          channel_id: this._defaultChannelId,
        },
      });

      return true;
    } catch (error) {
      console.error('[CmpService] Failed to identifyUser:', error);
      return false;
    }
  }

  /**
   * Track custom in-app marketing engagement action.
   */
  public async trackEvent(
    eventName: string,
    properties: Record<string, unknown> = {}
  ): Promise<boolean> {
    if (!eventName) {
      console.warn('[CmpService] trackEvent requires a valid eventName.');
      return false;
    }

    try {
      const payload: Record<string, unknown> = {
        ...properties,
        channel_id: this._defaultChannelId,
        user_id: this._currentUser?.userId,
        cif: this._currentUser?.cif,
      };

      // Emit to ActivityTracking
      await trackActivity({
        action: 'track_event',
        event_type: eventName,
        data: payload,
      });

      // Mirror to Firebase Analytics channel
      await logFirebaseAnalyticsEvent({
        action: eventName,
        user_id: this._currentUser?.userId,
        data: payload,
      });

      return true;
    } catch (error) {
      console.error(`[CmpService] Failed to trackEvent "${eventName}":`, error);
      return false;
    }
  }

  /**
   * Track product viewed, calculated, selected, or applied.
   */
  public async trackProductEngagement(params: CmpProductEngagementParams): Promise<boolean> {
    if (!params?.productId) {
      console.warn('[CmpService] trackProductEngagement requires a productId.');
      return false;
    }

    try {
      await trackActivity({
        action: 'track_product',
        product_id: params.productId,
        product_name: params.productName,
        product_action: params.productAction,
        category: params.category,
        data: {
          amount: params.amount,
          currency: params.currency,
          tenure_months: params.tenureMonths,
          user_id: this._currentUser?.userId,
          cif: this._currentUser?.cif,
          ...(params.extraData || {}),
        },
      });

      return true;
    } catch (error) {
      console.error('[CmpService] Failed to trackProductEngagement:', error);
      return false;
    }
  }

  /**
   * Track multi-step conversion funnel (e.g., Loan Journey Step 1 to Disbursement).
   */
  public async trackFunnelStep(params: CmpFunnelStepParams): Promise<boolean> {
    if (!params?.funnelName || params.stepNumber === undefined) {
      console.warn('[CmpService] trackFunnelStep requires funnelName and stepNumber.');
      return false;
    }

    try {
      await trackActivity({
        action: 'track_funnel',
        funnel_name: params.funnelName,
        step_number: params.stepNumber,
        step_name: params.stepName,
        data: {
          application_id: params.applicationId,
          product_code: params.productCode,
          user_id: this._currentUser?.userId,
          cif: this._currentUser?.cif,
          ...(params.extraData || {}),
        },
      });

      return true;
    } catch (error) {
      console.error('[CmpService] Failed to trackFunnelStep:', error);
      return false;
    }
  }

  /**
   * Track screen / view navigation for marketing impressions and dwell time.
   */
  public async trackScreen(screenName: string, fromScreen?: string): Promise<boolean> {
    if (!screenName) return false;

    try {
      await logTrace({
        data: {
          screen_name: screenName,
          from_screen: fromScreen || '',
          user_id: this._currentUser?.userId || '',
          timestamp: Date.now(),
        },
      });

      await trackActivity({
        action: 'track_event',
        event_type: 'SCREEN_VIEW',
        from_screen: fromScreen,
        text: screenName,
        data: {
          screen: screenName,
        },
      });

      return true;
    } catch (error) {
      console.error(`[CmpService] Failed to trackScreen "${screenName}":`, error);
      return false;
    }
  }

  /**
   * Subscribe to real-time activity tracking events.
   */
  public onActivityEvent(callback: (event: Record<string, unknown>) => void): () => void {
    const subscription: BizmobEventSubscription = addActivityTrackingListener(callback);
    return () => {
      subscription.remove();
    };
  }

  public async setLogging(enabled: boolean): Promise<boolean> {
    try {
      const response = await trackActivity({
        action: 'set_logging',
        enabled,
      });
      return response?.body?.result ?? true;
    } catch {
      return false;
    }
  }

  public async getHistory(): Promise<Array<Record<string, unknown>>> {
    try {
      const response = await trackActivity({
        action: 'get_history',
      });
      return (response?.body?.events as Array<Record<string, unknown>>) || [];
    } catch {
      return [];
    }
  }

  public async clearHistory(): Promise<boolean> {
    try {
      const response = await trackActivity({
        action: 'clear_history',
      });
      return response?.body?.result ?? true;
    } catch {
      return false;
    }
  }

  public resetForTesting(): void {
    this._isInitialized = false;
    this._currentUser = null;
  }
}

export const cmpService = new CmpService();
export default cmpService;

