import { appsFlyerService, AppsFlyerEventTypes } from './AppsFlyerService';
import { cmpService } from './CmpService';

/**
 * Standard stages of the end-to-end loan journey.
 */
export enum LoanJourneyStage {
  CALCULATOR_VIEWED = 'LOAN_CALCULATOR_VIEWED',
  SCHEME_SELECTED = 'LOAN_SCHEME_SELECTED',
  APPLICATION_STARTED = 'LOAN_APPLICATION_STARTED',
  CUSTOMER_INFO_SUBMITTED = 'LOAN_CUSTOMER_INFO_SUBMITTED',
  FINANCIAL_DSCR_EVALUATED = 'LOAN_FINANCIAL_EVALUATED',
  DOCUMENTS_UPLOADED = 'LOAN_DOCUMENTS_UPLOADED',
  APPLICATION_SUBMITTED = 'LOAN_APPLICATION_SUBMITTED',
  UNDERWRITING_APPROVED = 'LOAN_UNDERWRITING_APPROVED',
  UNDERWRITING_REJECTED = 'LOAN_UNDERWRITING_REJECTED',
  CONTRACT_SIGNED = 'LOAN_CONTRACT_SIGNED',
  DISBURSED = 'LOAN_DISBURSED',
}

export interface LoanJourneyMetadata {
  applicationId?: string;
  schemeCode: string;
  productName?: string;
  amount: number;
  tenureMonths: number;
  currency: string;
  interestRate?: number;
  customerNric?: string;
  customerCif?: string;
  customerSegment?: string;
  rejectionReason?: string;
}

export interface ILoanJourneyTracker {
  trackJourneyStage(stage: LoanJourneyStage, meta: LoanJourneyMetadata): Promise<void>;
  trackProductSelection(meta: LoanJourneyMetadata): Promise<void>;
  trackApplicationSubmitted(meta: LoanJourneyMetadata): Promise<void>;
  trackDisbursement(meta: LoanJourneyMetadata): Promise<void>;
}

/**
 * Coordinated tracker orchestrating parity between AppsFlyer (Attribution & Retargeting)
 * and CMP (Customer Marketing Platform & Engagement Channels).
 */
export class LoanJourneyTracker implements ILoanJourneyTracker {
  private static instance: LoanJourneyTracker;

  public static getInstance(): LoanJourneyTracker {
    if (!LoanJourneyTracker.instance) {
      LoanJourneyTracker.instance = new LoanJourneyTracker();
    }
    return LoanJourneyTracker.instance;
  }

  /**
   * Track any stage of the loan journey across both AppsFlyer and CMP.
   */
  public async trackJourneyStage(stage: LoanJourneyStage, meta: LoanJourneyMetadata): Promise<void> {
    const funnelStep = this.mapStageToStep(stage);

    // 1. Dispatch to CMP (Activity Tracking & Engagement)
    await cmpService.trackFunnelStep({
      funnelName: 'LOAN_ORIGINATION_JOURNEY',
      stepNumber: funnelStep.number,
      stepName: funnelStep.name,
      applicationId: meta.applicationId,
      productCode: meta.schemeCode,
      extraData: {
        stage,
        product_name: meta.productName,
        requested_amount: meta.amount,
        tenure_months: meta.tenureMonths,
        currency: meta.currency,
        customer_cif: meta.customerCif,
      },
    });

    // 2. Dispatch to AppsFlyer (MMP Retargeting & Lookalike Audiences)
    const appsFlyerEvent = this.mapStageToAppsFlyerEvent(stage);
    await appsFlyerService.logEvent(appsFlyerEvent, {
      af_content_id: meta.schemeCode,
      af_content_type: 'loan_product',
      af_currency: meta.currency,
      af_revenue: stage === LoanJourneyStage.DISBURSED ? meta.amount : undefined,
      af_price: meta.amount,
      application_id: meta.applicationId,
      tenure_months: meta.tenureMonths,
      stage_name: stage,
      customer_cif: meta.customerCif,
    });
  }

  public async trackProductSelection(meta: LoanJourneyMetadata): Promise<void> {
    await cmpService.trackProductEngagement({
      productId: meta.schemeCode,
      productName: meta.productName || meta.schemeCode,
      category: 'LOAN',
      productAction: 'SELECT',
      amount: meta.amount,
      currency: meta.currency,
      tenureMonths: meta.tenureMonths,
      extraData: {
        customer_cif: meta.customerCif,
      },
    });

    await appsFlyerService.logEvent(AppsFlyerEventTypes.CONTENT_VIEW, {
      af_content_id: meta.schemeCode,
      af_content_type: 'loan_product',
      af_currency: meta.currency,
      amount: meta.amount,
      tenure_months: meta.tenureMonths,
    });
  }

  public async trackApplicationSubmitted(meta: LoanJourneyMetadata): Promise<void> {
    await this.trackJourneyStage(LoanJourneyStage.APPLICATION_SUBMITTED, meta);

    // Dedicated CMP in-app event for immediate marketing triggers (SMS/Push follow-up)
    await cmpService.trackEvent('MKT_LOAN_APPLICATION_SUBMITTED', {
      application_id: meta.applicationId,
      scheme_code: meta.schemeCode,
      amount: meta.amount,
      currency: meta.currency,
      tenure_months: meta.tenureMonths,
    });
  }

  public async trackDisbursement(meta: LoanJourneyMetadata): Promise<void> {
    await this.trackJourneyStage(LoanJourneyStage.DISBURSED, meta);

    // Track purchase / conversion on AppsFlyer for ROAS & Lookalike audience modeling
    await appsFlyerService.logEvent(AppsFlyerEventTypes.PURCHASE, {
      af_content_id: meta.schemeCode,
      af_content_type: 'disbursement',
      af_revenue: meta.amount,
      af_currency: meta.currency,
      af_order_id: meta.applicationId,
      tenure_months: meta.tenureMonths,
    });

    // CMP marketing celebration & cross-sell trigger
    await cmpService.trackEvent('MKT_LOAN_DISBURSED', {
      application_id: meta.applicationId,
      disbursed_amount: meta.amount,
      currency: meta.currency,
    });
  }

  private mapStageToStep(stage: LoanJourneyStage): { number: number; name: string } {
    switch (stage) {
      case LoanJourneyStage.CALCULATOR_VIEWED:
        return { number: 1, name: 'CALCULATOR_VIEWED' };
      case LoanJourneyStage.SCHEME_SELECTED:
        return { number: 2, name: 'SCHEME_SELECTED' };
      case LoanJourneyStage.APPLICATION_STARTED:
        return { number: 3, name: 'APPLICATION_STARTED' };
      case LoanJourneyStage.CUSTOMER_INFO_SUBMITTED:
        return { number: 4, name: 'CUSTOMER_INFO_SUBMITTED' };
      case LoanJourneyStage.FINANCIAL_DSCR_EVALUATED:
        return { number: 5, name: 'FINANCIAL_DSCR_EVALUATED' };
      case LoanJourneyStage.DOCUMENTS_UPLOADED:
        return { number: 6, name: 'DOCUMENTS_UPLOADED' };
      case LoanJourneyStage.APPLICATION_SUBMITTED:
        return { number: 7, name: 'APPLICATION_SUBMITTED' };
      case LoanJourneyStage.UNDERWRITING_APPROVED:
        return { number: 8, name: 'UNDERWRITING_APPROVED' };
      case LoanJourneyStage.UNDERWRITING_REJECTED:
        return { number: 8, name: 'UNDERWRITING_REJECTED' };
      case LoanJourneyStage.CONTRACT_SIGNED:
        return { number: 9, name: 'CONTRACT_SIGNED' };
      case LoanJourneyStage.DISBURSED:
        return { number: 10, name: 'DISBURSED' };
      default:
        return { number: 99, name: 'UNKNOWN' };
    }
  }

  private mapStageToAppsFlyerEvent(stage: LoanJourneyStage): string {
    switch (stage) {
      case LoanJourneyStage.CALCULATOR_VIEWED:
        return 'af_loan_calculator_viewed';
      case LoanJourneyStage.SCHEME_SELECTED:
        return AppsFlyerEventTypes.CONTENT_VIEW;
      case LoanJourneyStage.APPLICATION_STARTED:
        return AppsFlyerEventTypes.INITIATED_CHECKOUT;
      case LoanJourneyStage.CUSTOMER_INFO_SUBMITTED:
        return 'af_loan_customer_info';
      case LoanJourneyStage.FINANCIAL_DSCR_EVALUATED:
        return 'af_loan_dscr_evaluated';
      case LoanJourneyStage.DOCUMENTS_UPLOADED:
        return 'af_loan_docs_uploaded';
      case LoanJourneyStage.APPLICATION_SUBMITTED:
        return 'af_loan_application_submitted';
      case LoanJourneyStage.UNDERWRITING_APPROVED:
        return 'af_loan_approved';
      case LoanJourneyStage.UNDERWRITING_REJECTED:
        return 'af_loan_rejected';
      case LoanJourneyStage.CONTRACT_SIGNED:
        return 'af_loan_contract_signed';
      case LoanJourneyStage.DISBURSED:
        return AppsFlyerEventTypes.PURCHASE;
      default:
        return 'af_custom_loan_event';
    }
  }
}

export const loanJourneyTracker = LoanJourneyTracker.getInstance();

